package cn.zhuatech.lims.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class SampleStabilityService{public Result evaluate(Request r){int remaining=r.stabilityWindowHours()-r.ageHours();List<String> reasons=new ArrayList<>();if(remaining<0)reasons.add("样本已超过稳定性时限");if(r.storageExcursion())reasons.add("样本存储发生温度偏离");if(!r.chainOfCustodyComplete())reasons.add("样本交接链记录不完整");String status=remaining<0||r.storageExcursion()&&r.criticalStudy()?"RECOLLECT":!r.chainOfCustodyComplete()||r.storageExcursion()||remaining<=2?"HOLD":"ACCEPT";if(reasons.isEmpty())reasons.add("样本稳定性和交接证据满足检测条件");return new Result(remaining,status,r.repeatSampleAvailable(),reasons);}
 public record Request(@NotBlank String sampleId,@Min(0) int ageHours,@Min(1) int stabilityWindowHours,@NotNull Boolean storageExcursion,@NotNull Boolean chainOfCustodyComplete,@NotNull Boolean repeatSampleAvailable,@NotNull Boolean criticalStudy){}public record Result(int stabilityHoursRemaining,String status,boolean repeatSampleAvailable,List<String> reasons){} }
